const forms = [{ form: 'S-1', stage: 'Initial registration' }, { form: 'F-1', stage: 'Foreign issuer registration' }, { form: 'EFFECT', stage: 'Registration effective' }, { form: '424B4', stage: 'Final prospectus' }];
const clean = (value) => (value || '').replace(/<[^>]*>/g, '').replace(/\s+/g, ' ').trim();
const tag = (xml, name) => ((xml.match(new RegExp(`<${name}[^>]*>([\\s\\S]*?)</${name}>`, 'i'))) || [, ''])[1];

async function getSecFeed() {
  const batches = await Promise.all(forms.map(async (form) => {
    const response = await fetch(`https://www.sec.gov/cgi-bin/browse-edgar?action=getcurrent&type=${form.form}&output=atom`, { headers: { 'User-Agent': 'IPO Pulse Workbench contact@ipo-pulse.app' } });
    if (!response.ok) return [];
    const xml = await response.text();
    return [...xml.matchAll(/<entry>([\s\S]*?)<\/entry>/gi)].slice(0, 10).map((match) => {
      const entry = match[1];
      return { title: clean(tag(entry, 'title')), published: tag(entry, 'updated') || tag(entry, 'published'), link: (entry.match(/<link[^>]+href="([^"]+)"/i) || [, ''])[1], form: form.form, stage: form.stage };
    }).filter((item) => item.title && item.link);
  }));
  return batches.flat().sort((a, b) => new Date(b.published) - new Date(a.published));
}

const page = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>IPO Pulse Workbench</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f6f8;color:#13243a;font-family:Arial,sans-serif}.top{background:#101d31;color:#fff;padding:16px 6%;display:flex;justify-content:space-between}.live{background:#e84845;padding:4px 7px;border-radius:4px;font-size:10px}.wrap{max-width:1080px;margin:auto;padding:28px 22px}.hero{display:flex;justify-content:space-between;gap:20px;align-items:end}.hero h1{font-size:42px;margin:4px 0}.hero p,.muted{color:#617288}.panel{background:#fff;border:1px solid #dbe3eb;border-radius:10px;padding:16px;margin-top:18px}.status{display:flex;gap:9px;align-items:center;font-size:13px}.dot{width:9px;height:9px;border-radius:50%;background:#22b47b}.list{margin-top:12px}.item{position:relative;border-left:3px solid #20a271;background:#fff;border-radius:8px;margin:8px 0;padding:16px 155px 16px 18px}.item h3{margin:5px 0;font-size:18px}.item p{margin:6px 0;color:#627286;font-size:13px}.meta{font-size:12px;color:#5f7086}.source{position:absolute;right:16px;top:19px;color:#1261cf;font-weight:bold;text-decoration:none}.tag{font-size:11px;color:#167154;font-weight:bold}button{border:0;border-radius:7px;background:#1366d6;color:#fff;font-weight:bold;padding:10px 12px;cursor:pointer}@media(max-width:650px){.hero{display:block}.hero h1{font-size:32px}.item{padding-right:16px}.source{position:static;display:inline-block;margin-top:8px}}</style></head><body><header class="top"><b>IPO PULSE <span class="live">LIVE</span></b><span>IPO Intelligence Workbench</span></header><main class="wrap"><section class="hero"><div><div class="tag">TIME-FIRST IPO INTELLIGENCE</div><h1>Filings before headlines.</h1><p>Official SEC EDGAR data | automatic refresh | source-document traceability</p></div><button id="refresh">Refresh SEC feed</button></section><section class="panel"><div class="status"><span class="dot"></span><b id="status">Connecting to SEC EDGAR</b><span class="muted" id="stamp"></span></div><div class="list" id="list"></div></section></main><script>const list=document.querySelector('#list'),status=document.querySelector('#status'),stamp=document.querySelector('#stamp');const esc=v=>String(v).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));async function load(){status.textContent='Syncing SEC EDGAR';try{const response=await fetch('/api/sec-ipo',{cache:'no-store'}),payload=await response.json();if(!response.ok)throw Error(payload.error);list.innerHTML=payload.items.map(item=>'<article class="item"><div class="tag">SEC '+esc(item.form)+' | '+esc(item.stage)+'</div><h3>'+esc(item.title)+'</h3><p>Official SEC filing event. Open the source document to confirm issuer, offering structure and current status.</p><div class="meta">'+new Date(item.published).toLocaleString()+'</div><a class="source" target="_blank" rel="noreferrer" href="'+esc(item.link)+'">Source document -&gt;</a></article>').join('');status.textContent='SEC EDGAR connected';stamp.textContent='Updated '+new Date(payload.fetchedAt).toLocaleTimeString()}catch(error){status.textContent='Data temporarily unavailable';stamp.textContent='Please refresh shortly'}}document.querySelector('#refresh').onclick=load;load();setInterval(load,60000);</script></body></html>`;

export default { async fetch(request) { const url = new URL(request.url); if (url.pathname === '/api/sec-ipo') { try { return Response.json({ fetchedAt: new Date().toISOString(), items: await getSecFeed() }, { headers: { 'Cache-Control': 'no-store' } }); } catch (error) { return Response.json({ error: error.message }, { status: 502 }); } } return new Response(page, { headers: { 'content-type': 'text/html; charset=utf-8' } }); } };
